-- Demo data for the whole system, built around the students in
-- prisma/demo-data/high_school_students.csv.
--
-- GENERATED by scripts/generate-demo-data.mjs from prisma/demo-data/populate.sql
-- and the CSV. Edit those and regenerate; do not edit the migration by hand.
--
-- Runs once per database (Prisma records it). Everything is linked to the
-- users that already exist: the school with the most users, and its ADMIN,
-- HEAD, BURSAR, DIRECTOR, LIBRARIAN and TEACHER accounts (another user stands
-- in where a role is missing). With no users at all it does nothing.
--
-- It starts by emptying every table except users and logins, so the school
-- holds only this demo data afterwards.
--
-- Calendar: academic year 2026; Terms 1 and 2 closed, Term 3 open
-- (8 Sep – 4 Dec). Payments, marks and requests are dated up to 13 Oct 2026.

-- Deterministic pseudo-random number in [0, 1) for a text key, so the data is
-- the same on every database.
CREATE OR REPLACE FUNCTION demo_rand(k TEXT) RETURNS DOUBLE PRECISION
LANGUAGE SQL IMMUTABLE AS $$
  SELECT ((('x' || substr(md5(k), 1, 8))::bit(32)::int)::bigint + 2147483648) / 4294967296.0
$$;

-- ZIMSEC O-Level grades.
CREATE OR REPLACE FUNCTION demo_grade(p NUMERIC) RETURNS TEXT
LANGUAGE SQL IMMUTABLE AS $$
  SELECT CASE WHEN p >= 75 THEN 'A' WHEN p >= 65 THEN 'B' WHEN p >= 50 THEN 'C'
              WHEN p >= 40 THEN 'D' WHEN p >= 30 THEN 'E' ELSE 'U' END
$$;

CREATE TEMP TABLE demo_csv (
  adm               TEXT PRIMARY KEY,
  first_name        TEXT NOT NULL,
  surname           TEXT NOT NULL,
  gender            TEXT NOT NULL,
  dob               DATE NOT NULL,
  form              INT  NOT NULL,
  stream            TEXT NOT NULL,
  class_name        TEXT NOT NULL,
  enrollment_year   INT  NOT NULL,
  guardian_name     TEXT NOT NULL,
  relationship      TEXT NOT NULL,
  relationship_note TEXT,
  guardian_phone    TEXT NOT NULL,
  house_number      TEXT,
  suburb            TEXT,
  city              TEXT,
  address           TEXT,
  status            TEXT NOT NULL
);

-- @@STUDENTS@@

DO $demo$
DECLARE
  sid          TEXT;
  admin_id     TEXT;
  head_id      TEXT;
  bursar_id    TEXT;
  director_id  TEXT;
  librarian_id TEXT;
  teachers     TEXT[];
  members      TEXT[];
  nt           INT;
  nm           INT;
  wipe         TEXT;
BEGIN
  -- ── Who the data belongs to ────────────────────────────────────────────────
  SELECT "schoolId" INTO sid FROM "User"
   GROUP BY "schoolId" ORDER BY count(*) DESC, "schoolId" LIMIT 1;
  IF sid IS NULL THEN
    RAISE NOTICE 'Demo data skipped: there are no users to link it to.';
    RETURN;
  END IF;

  SELECT id INTO admin_id FROM "User" WHERE "schoolId" = sid AND role = 'ADMIN' AND active ORDER BY "createdAt", id LIMIT 1;
  IF admin_id IS NULL THEN
    SELECT id INTO admin_id FROM "User" WHERE "schoolId" = sid ORDER BY active DESC, "createdAt", id LIMIT 1;
  END IF;
  head_id      := coalesce((SELECT id FROM "User" WHERE "schoolId" = sid AND role = 'HEAD'      AND active ORDER BY "createdAt", id LIMIT 1), admin_id);
  bursar_id    := coalesce((SELECT id FROM "User" WHERE "schoolId" = sid AND role = 'BURSAR'    AND active ORDER BY "createdAt", id LIMIT 1), admin_id);
  director_id  := coalesce((SELECT id FROM "User" WHERE "schoolId" = sid AND role = 'DIRECTOR'  AND active ORDER BY "createdAt", id LIMIT 1), head_id);
  librarian_id := coalesce((SELECT id FROM "User" WHERE "schoolId" = sid AND role = 'LIBRARIAN' AND active ORDER BY "createdAt", id LIMIT 1), admin_id);
  SELECT array_agg(id ORDER BY "createdAt", id) INTO teachers FROM "User" WHERE "schoolId" = sid AND role = 'TEACHER' AND active;
  IF teachers IS NULL THEN teachers := ARRAY[head_id]; END IF;
  nt := array_length(teachers, 1);

  -- ── Start from empty (users and logins are kept) ───────────────────────────
  SELECT string_agg(format('public.%I', tablename), ', ') INTO wipe
    FROM pg_tables
   WHERE schemaname = 'public'
     AND tablename NOT IN ('User', 'Account', 'Session', 'VerificationToken', 'School', '_prisma_migrations');
  IF wipe IS NOT NULL THEN
    EXECUTE 'TRUNCATE TABLE ' || wipe || ' RESTART IDENTITY';
  END IF;

  -- ── Academic structure ─────────────────────────────────────────────────────
  INSERT INTO "Level" (id, "schoolId", name, "order", category)
  SELECT 'demo-level-' || o, sid, 'Form ' || o, o, (CASE WHEN o <= 4 THEN 'O_LEVEL' ELSE 'A_LEVEL' END)::"LevelCategory"
    FROM generate_series(1, 6) AS o;

  INSERT INTO "AcademicYear" (id, "schoolId", year, "startDate", "endDate", "createdAt")
  VALUES ('demo-year-2026', sid, 2026, DATE '2026-01-01', DATE '2026-12-31', TIMESTAMP '2026-01-05 09:00');

  INSERT INTO "AcademicTerm" (id, "schoolId", "academicYearId", "termNumber", name, "startDate", "endDate", status, "closedAt", "closedById", "createdAt")
  VALUES
    ('demo-term-1', sid, 'demo-year-2026', 1, 'Term 1 2026', DATE '2026-01-13', DATE '2026-04-10', 'CLOSED', TIMESTAMP '2026-04-10 16:00', head_id, TIMESTAMP '2026-01-05 09:00'),
    ('demo-term-2', sid, 'demo-year-2026', 2, 'Term 2 2026', DATE '2026-05-05', DATE '2026-08-07', 'CLOSED', TIMESTAMP '2026-08-07 16:00', head_id, TIMESTAMP '2026-01-05 09:00'),
    ('demo-term-3', sid, 'demo-year-2026', 3, 'Term 3 2026', DATE '2026-09-08', DATE '2026-12-04', 'OPEN',   NULL,                         NULL,    TIMESTAMP '2026-01-05 09:00');

  INSERT INTO "SchoolClass" (id, "schoolId", name, "levelId", stream, capacity, "classTeacherId", active, "createdAt")
  SELECT 'demo-class-f' || c.form || '-' || lower(c.stream), sid, c.class_name, 'demo-level-' || c.form, c.stream, 45,
         teachers[1 + ((c.form - 1) * 3 + CASE c.stream WHEN 'North' THEN 0 WHEN 'South' THEN 1 ELSE 2 END) % nt],
         true, TIMESTAMP '2026-01-06 09:00'
    FROM (SELECT DISTINCT form, stream, class_name FROM demo_csv) AS c;

  -- ── Students, guardians, enrollments ───────────────────────────────────────
  INSERT INTO "Student" (id, "schoolId", "admissionNumber", "firstName", surname, "fullName", gender, "dateOfBirth",
                         "admissionDate", status, "currentClassId", "houseNumber", suburb, city, address, "portalToken", "createdAt")
  SELECT 'demo-' || lower(c.adm), sid, c.adm, c.first_name, c.surname, c.first_name || ' ' || c.surname,
         c.gender::"Gender", c.dob, make_date(c.enrollment_year, 1, 13), c.status::"StudentStatus",
         'demo-class-f' || c.form || '-' || lower(c.stream), c.house_number, c.suburb, c.city, c.address,
         md5(c.adm || random()::text || clock_timestamp()::text),
         make_date(c.enrollment_year, 1, 13) + TIME '09:00'
    FROM demo_csv c;

  INSERT INTO "Guardian" (id, "schoolId", "fullName", phone, address, "createdAt")
  SELECT 'demo-guardian-' || lower(c.adm), sid, c.guardian_name, c.guardian_phone, c.address,
         make_date(c.enrollment_year, 1, 13) + TIME '09:00'
    FROM demo_csv c;

  INSERT INTO "StudentGuardian" ("studentId", "guardianId", relationship, "relationshipNote", "isPrimary", "isFeePayer", "canReceiveSms", "createdAt")
  SELECT 'demo-' || lower(c.adm), 'demo-guardian-' || lower(c.adm), c.relationship::"GuardianRelationship", c.relationship_note,
         true, true, true, make_date(c.enrollment_year, 1, 13) + TIME '09:00'
    FROM demo_csv c;

  CREATE TEMP TABLE demo_st (
    student_id TEXT, k TEXT, form INT, class_id TEXT,
    term_id TEXT, term_no INT, term_name TEXT, term_start DATE, term_end DATE, term_closed BOOLEAN
  );
  INSERT INTO demo_st
  SELECT 'demo-' || lower(c.adm), lower(c.adm), c.form, 'demo-class-f' || c.form || '-' || lower(c.stream),
         t.id, t."termNumber", t.name, t."startDate", t."endDate", t.status = 'CLOSED'
    FROM demo_csv c CROSS JOIN "AcademicTerm" t
   WHERE t."schoolId" = sid;

  INSERT INTO "Enrollment" (id, "schoolId", "studentId", "classId", "termId", status, "startDate", "endDate", "createdAt")
  SELECT 'demo-enr-' || st.k || '-t' || st.term_no, sid, st.student_id, st.class_id, st.term_id, 'ACTIVE',
         st.term_start, CASE WHEN st.term_closed THEN st.term_end::timestamp END, st.term_start
    FROM demo_st st;

  -- ── Fees ───────────────────────────────────────────────────────────────────
  INSERT INTO "FeeStructure" (id, "schoolId", "levelId", "termId", label, currency, amount, "createdAt")
  SELECT 'demo-fee-t' || t."termNumber" || '-' || f.code, sid, f.level_id, t.id, f.label, f.currency::"Currency", f.amount,
         t."startDate" - 7 + TIME '10:00'
    FROM "AcademicTerm" t
   CROSS JOIN (VALUES
     ('f1-tuition',   'demo-level-1', 'Tuition',        'USD',  280.00),
     ('f2-tuition',   'demo-level-2', 'Tuition',        'USD',  280.00),
     ('f3-tuition',   'demo-level-3', 'Tuition',        'USD',  300.00),
     ('f4-tuition',   'demo-level-4', 'Tuition',        'USD',  320.00),
     ('f5-tuition',   'demo-level-5', 'Tuition',        'USD',  360.00),
     ('f6-tuition',   'demo-level-6', 'Tuition',        'USD',  360.00),
     ('f1-transport', 'demo-level-1', 'Transport Levy', 'USD',   40.00),
     ('f2-transport', 'demo-level-2', 'Transport Levy', 'USD',   40.00),
     ('f3-transport', 'demo-level-3', 'Transport Levy', 'USD',   45.00),
     ('f4-transport', 'demo-level-4', 'Transport Levy', 'USD',   45.00),
     ('f5-transport', 'demo-level-5', 'Transport Levy', 'USD',   45.00),
     ('f6-transport', 'demo-level-6', 'Transport Levy', 'USD',   45.00),
     ('all-sports',   NULL,           'Sports Levy',    'ZIG', 1450.00)
   ) AS f(code, level_id, label, currency, amount)
   WHERE t."schoolId" = sid;

  INSERT INTO "Charge" (id, "schoolId", "studentId", "termId", label, currency, amount, "issuedAt")
  SELECT 'demo-chg-' || st.k || '-' || fs.id, sid, st.student_id, st.term_id, fs.label, fs.currency, fs.amount,
         st.term_start + TIME '08:00'
    FROM demo_st st
    JOIN "FeeStructure" fs ON fs."termId" = st.term_id AND (fs."levelId" IS NULL OR fs."levelId" = 'demo-level-' || st.form);

  INSERT INTO "ExchangeRate" (id, "schoolId", "usdToZig", "setBy", note, "createdAt")
  SELECT 'demo-rate-' || w, sid, round((26.40 + w * 0.025 + (demo_rand('rate' || w) - 0.5) * 0.12)::numeric, 2),
         bursar_id, 'Interbank rate', TIMESTAMP '2025-12-29 08:00' + w * INTERVAL '7 days'
    FROM generate_series(0, 41) AS w;

  -- ── Payments ───────────────────────────────────────────────────────────────
  -- Each family has a steady paying habit (r), nudged a little each term.
  -- Terms 1–2: most families cleared; Term 3 (open): about half have cleared,
  -- some paid part, some nothing yet. Non-cash payments from the last week
  -- are still waiting for the Head to verify them.
  CREATE TEMP TABLE demo_pay (
    id TEXT, student_id TEXT, term_no INT, kind TEXT, cur TEXT, amount NUMERIC,
    recorded_at TIMESTAMP, method TEXT, fee_label TEXT
  );
  INSERT INTO demo_pay
  WITH due AS (
    SELECT st.*,
           (SELECT sum(c.amount) FROM "Charge" c
             WHERE c."studentId" = st.student_id AND c."termId" = st.term_id AND c.currency = 'USD') AS usd_due,
           demo_rand(st.k || '-payer') + (demo_rand(st.k || '-t' || st.term_no || '-jitter') - 0.5) * 0.1 AS r,
           demo_rand(st.k || '-t' || st.term_no || '-split') AS split,
           demo_rand(st.k || '-t' || st.term_no || '-levy')  AS levy,
           CASE WHEN st.term_closed THEN 0.85 ELSE 0.55 END AS full_cut,
           CASE WHEN st.term_closed THEN 0.95 ELSE 0.82 END AS part_cut
      FROM demo_st st
  ), parts AS (
    SELECT k, student_id, term_no, term_name, 'full' AS kind, 'USD' AS cur, usd_due AS amount,
           term_start - 10 + floor(demo_rand(k || term_no || 'd-full') * 25)::int AS day, 'Tuition & Transport' AS what
      FROM due WHERE r < full_cut AND split >= 0.35
    UNION ALL
    SELECT k, student_id, term_no, term_name, 'inst1', 'USD', round(usd_due * 0.6),
           term_start - 10 + floor(demo_rand(k || term_no || 'd-i1') * 20)::int, 'Tuition & Transport (instalment 1)'
      FROM due WHERE r < full_cut AND split < 0.35
    UNION ALL
    SELECT k, student_id, term_no, term_name, 'inst2', 'USD', usd_due - round(usd_due * 0.6),
           term_start + 15 + floor(demo_rand(k || term_no || 'd-i2') * 21)::int, 'Tuition & Transport (instalment 2)'
      FROM due WHERE r < full_cut AND split < 0.35
    UNION ALL
    SELECT k, student_id, term_no, term_name, 'part', 'USD',
           greatest(20, round(usd_due * (0.35 + 0.5 * demo_rand(k || term_no || 'amt')) / 5) * 5),
           term_start - 10 + floor(demo_rand(k || term_no || 'd-part') * 46)::int, 'Tuition (part payment)'
      FROM due WHERE r >= full_cut AND r < part_cut
    UNION ALL
    SELECT k, student_id, term_no, term_name, 'levy', 'ZIG', 1450,
           term_start - 5 + floor(demo_rand(k || term_no || 'd-levy') * 40)::int, 'Sports Levy'
      FROM due WHERE (r < full_cut AND levy < 0.95) OR (r >= full_cut AND r < part_cut AND levy < 0.5)
  )
  SELECT 'demo-pay-' || p.k || '-t' || p.term_no || '-' || p.kind, p.student_id, p.term_no, p.kind, p.cur, p.amount,
         least(p.day + TIME '08:00' + floor(demo_rand(p.k || p.term_no || p.kind || 'min') * 480) * INTERVAL '1 minute',
               TIMESTAMP '2026-10-13 16:30'),
         CASE WHEN m.v < 0.38 THEN 'CASH' WHEN m.v < 0.70 THEN 'ECOCASH' WHEN m.v < 0.85 THEN 'SWIPE' ELSE 'ZIPIT' END,
         p.term_name || ' ' || p.what
    FROM parts p
   CROSS JOIN LATERAL (SELECT demo_rand(p.k || p.term_no || p.kind || 'method') AS v) m;

  INSERT INTO "Payment" (id, "schoolId", "studentId", currency, amount, method, reference, "feeLabel", status,
                         "recordedBy", "verifiedBy", "recordedAt", "verifiedAt", "paidInZig", "zigAmountPaid", "exchangeRateUsed")
  SELECT p.id, sid, p.student_id, p.cur::"Currency", p.amount, p.method::"PaymentMethod",
         CASE p.method WHEN 'ECOCASH' THEN 'EC-' WHEN 'SWIPE' THEN 'SW-' WHEN 'ZIPIT' THEN 'ZP-' END
           || lpad(floor(demo_rand(p.id || 'ref') * 9999999)::int::text, 7, '0'),
         p.fee_label, s.status::"PaymentStatus", bursar_id,
         CASE WHEN s.status = 'VERIFIED' THEN CASE WHEN p.method = 'CASH' THEN bursar_id ELSE head_id END END,
         p.recorded_at,
         CASE WHEN s.status = 'VERIFIED' THEN CASE WHEN p.method = 'CASH' THEN p.recorded_at ELSE p.recorded_at + INTERVAL '26 hours' END END,
         z.in_zig,
         CASE WHEN z.in_zig THEN round(p.amount * z.rate, 2) END,
         CASE WHEN z.in_zig THEN round(z.rate, 2) END
    FROM demo_pay p
   CROSS JOIN LATERAL (
     SELECT CASE WHEN p.method <> 'CASH' AND p.recorded_at >= TIMESTAMP '2026-10-07' THEN 'PENDING' ELSE 'VERIFIED' END AS status
   ) s
   CROSS JOIN LATERAL (
     SELECT p.cur = 'USD' AND p.method = 'CASH' AND demo_rand(p.id || 'zig') < 0.12 AS in_zig,
            (SELECT r."usdToZig" FROM "ExchangeRate" r
              WHERE r."schoolId" = sid AND r."createdAt" <= p.recorded_at
              ORDER BY r."createdAt" DESC LIMIT 1) AS rate
   ) z;

  -- A few duplicate entries that were caught and voided by the Director.
  INSERT INTO "Payment" (id, "schoolId", "studentId", currency, amount, method, reference, "feeLabel", status,
                         "recordedBy", "recordedAt", "voidedBy", "voidedAt", "paidInZig", "zigAmountPaid", "exchangeRateUsed")
  SELECT p.id || '-dup', sid, p."studentId", p.currency, p.amount, p.method, p.reference, p."feeLabel", 'VOIDED',
         bursar_id, p."recordedAt" + INTERVAL '7 minutes', director_id, p."recordedAt" + INTERVAL '1 day',
         p."paidInZig", p."zigAmountPaid", p."exchangeRateUsed"
    FROM "Payment" p
   WHERE p."schoolId" = sid AND p.id LIKE 'demo-pay-%-full' AND p.status = 'VERIFIED' AND demo_rand(p.id || 'dup') < 0.03;

  -- ── Expenses ───────────────────────────────────────────────────────────────
  INSERT INTO "Expense" (id, "schoolId", category, currency, amount, note, "spentOn", "recordedBy", status, "voidedBy", "createdAt")
  SELECT 'demo-exp-' || e.code || '-' || m, sid, e.category, e.currency::"Currency",
         round((e.base + e.spread * demo_rand(e.code || m)) / 5) * 5,
         e.note || ' — ' || to_char(make_date(2026, m, 1), 'FMMonth YYYY'),
         make_date(2026, m, e.day), bursar_id,
         (CASE WHEN (e.code, m) IN (('fuel-b', 3), ('stationery', 6)) THEN 'VOIDED' ELSE 'ACTIVE' END)::"ExpenseStatus",
         CASE WHEN (e.code, m) IN (('fuel-b', 3), ('stationery', 6)) THEN director_id END,
         make_date(2026, m, e.day) + TIME '10:00'
    FROM generate_series(1, 10) AS m
   CROSS JOIN (VALUES
     ('salaries',    'Staff Salaries',    'USD', 6400, 600,  25, 'Teaching and support staff salaries'),
     ('zesa',        'Utilities',         'ZIG', 9500, 3000,  4, 'ZESA prepaid electricity'),
     ('water',       'Utilities',         'ZIG', 3200, 900,  12, 'City of Harare water and rates'),
     ('fuel-a',      'Fuel',              'USD',  260, 120,   7, 'Diesel for the school bus'),
     ('fuel-b',      'Fuel',              'USD',  180, 90,   21, 'Petrol for the admin vehicle'),
     ('canteen-a',   'Canteen Groceries', 'ZIG', 7200, 2400,  3, 'Canteen groceries, Mbare Musika'),
     ('canteen-b',   'Canteen Groceries', 'ZIG', 6800, 2400, 17, 'Canteen groceries, wholesale'),
     ('stationery',  'Stationery',        'USD',  120, 160,  10, 'Exercise books, chalk and printing paper'),
     ('maintenance', 'Maintenance',       'USD',   90, 420,  15, 'Repairs and maintenance')
   ) AS e(code, category, currency, base, spread, day, note)
   WHERE make_date(2026, m, e.day) <= DATE '2026-10-13';

  -- ── Expense requests ───────────────────────────────────────────────────────
  INSERT INTO "ExpenseRequest" (id, "schoolId", "requestNumber", title, type, department, justification, currency,
                                "estimatedTotal", status, "requestedById", "requestedAt",
                                "approvedById", "approvedAt", "rejectedById", "rejectedAt", "rejectionReason",
                                "disbursedById", "disbursedAt", "disbursementNote", "paymentMethod", "createdAt")
  SELECT 'demo-req-' || r.n, sid, 'REQ-2026-' || r.n, r.title, r.type::"ExpenseRequestType", r.department, r.justification,
         r.currency::"Currency", 0, r.status::"RequestStatus",
         CASE r.requester WHEN 't1' THEN teachers[1] WHEN 't2' THEN teachers[1 + 1 % nt] WHEN 'bursar' THEN bursar_id ELSE admin_id END,
         r.requested_at,
         CASE WHEN r.approved_at IS NOT NULL THEN head_id END, r.approved_at,
         CASE WHEN r.rejected_at IS NOT NULL THEN head_id END, r.rejected_at, r.reason,
         CASE WHEN r.disbursed_at IS NOT NULL THEN bursar_id END, r.disbursed_at,
         CASE WHEN r.disbursed_at IS NOT NULL THEN 'Paid in full' END,
         r.method::"PaymentMethod", r.requested_at
    FROM (VALUES
      ('001', 'Laboratory chemicals for Form 3 practicals', 'PURCHASE_ORDER', 'Science Department',     'Stock ran out during Term 1 practicals',                  'USD', 'DISBURSED', 't1',     TIMESTAMP '2026-02-09 09:15', TIMESTAMP '2026-02-10 11:00', NULL::timestamp,              NULL,                                                   TIMESTAMP '2026-02-12 10:00', 'CASH'),
      ('002', 'School bus service and brake pads',          'MAINTENANCE',    'Transport',              'Bus is due for its 20 000 km service',                    'USD', 'DISBURSED', 'admin',  TIMESTAMP '2026-03-02 08:30', TIMESTAMP '2026-03-03 10:00', NULL,                         NULL,                                                   TIMESTAMP '2026-03-05 09:30', 'ZIPIT'),
      ('003', 'Athletics kit for the inter-schools gala',   'PURCHASE_ORDER', 'Sports',                 'Team needs vests and spikes for the provincial gala',     'USD', 'REJECTED',  't2',     TIMESTAMP '2026-04-14 13:00', NULL,                         TIMESTAMP '2026-04-16 09:00', 'Term 1 budget is spent. Please resubmit in Term 2.',   NULL,                         NULL),
      ('004', 'Diesel for the standby generator',           'FUEL',           'Administration',         'Load-shedding schedule has increased',                    'USD', 'DISBURSED', 'admin',  TIMESTAMP '2026-05-18 08:00', TIMESTAMP '2026-05-18 14:00', NULL,                         NULL,                                                   TIMESTAMP '2026-05-19 08:30', 'CASH'),
      ('005', 'Form 4 Mathematics revision textbooks',      'PURCHASE_ORDER', 'Mathematics Department', 'Revision guides for the November ZIMSEC examinations',    'USD', 'DISBURSED', 't1',     TIMESTAMP '2026-06-08 10:00', TIMESTAMP '2026-06-09 09:00', NULL,                         NULL,                                                   TIMESTAMP '2026-06-15 11:00', 'ZIPIT'),
      ('006', 'ZESA electricity arrears',                   'UTILITY_BILL',   'Administration',         'Arrears for June and July to avoid disconnection',        'ZIG', 'DISBURSED', 'bursar', TIMESTAMP '2026-07-21 09:00', TIMESTAMP '2026-07-22 10:30', NULL,                         NULL,                                                   TIMESTAMP '2026-07-24 12:00', 'ECOCASH'),
      ('007', 'Salary advance for the groundsman',          'SALARY_ADVANCE', 'Administration',         'Family medical emergency',                                'USD', 'REJECTED',  'admin',  TIMESTAMP '2026-08-25 08:45', NULL,                         TIMESTAMP '2026-08-26 15:00', 'Advances are paused until Term 3 fees are collected.', NULL,                         NULL),
      ('008', 'Roof repairs, Block C',                      'MAINTENANCE',    'Administration',         'Two classrooms leak when it rains',                       'USD', 'APPROVED',  'admin',  TIMESTAMP '2026-09-28 09:00', TIMESTAMP '2026-09-30 11:00', NULL,                         NULL,                                                   NULL,                         NULL),
      ('009', 'Toner and paper for end-of-year exams',      'PURCHASE_ORDER', 'Exams Office',           'Printing of Form 1–3 end-of-year papers',                 'USD', 'PENDING',   't2',     TIMESTAMP '2026-10-05 10:20', NULL,                         NULL,                         NULL,                                                   NULL,                         NULL),
      ('010', 'Two laptops for the computer lab',           'PURCHASE_ORDER', 'IT Department',          'Two lab machines failed and cannot be repaired',          'USD', 'PENDING',   't1',     TIMESTAMP '2026-10-09 09:00', NULL,                         NULL,                         NULL,                                                   NULL,                         NULL),
      ('011', 'Fuel for the Form 4 Geography field trip',   'FUEL',           'Geography Department',   'Field work at Lake Chivero for the coursework component', 'USD', 'PENDING',   't2',     TIMESTAMP '2026-10-13 08:40', NULL,                         NULL,                         NULL,                                                   NULL,                         NULL),
      ('012', 'Football kits',                              'PURCHASE_ORDER', 'Sports',                 'Current kits are torn',                                   'USD', 'DRAFT',     't1',     TIMESTAMP '2026-10-12 14:10', NULL,                         NULL,                         NULL,                                                   NULL,                         NULL)
    ) AS r(n, title, type, department, justification, currency, status, requester, requested_at, approved_at, rejected_at, reason, disbursed_at, method);

  INSERT INTO "ExpenseRequestItem" (id, "requestId", description, quantity, "unitPrice", total)
  SELECT 'demo-req-' || i.n || '-item-' || i.idx, 'demo-req-' || i.n, i.description, i.qty, i.price, i.qty * i.price
    FROM (VALUES
      ('001', 1, 'Hydrochloric acid, 2.5 L',          2,    18.00),
      ('001', 2, 'Copper sulphate, 500 g',            3,    12.00),
      ('001', 3, 'Litmus paper (pack)',              10,     4.50),
      ('002', 1, 'Full service (labour and oils)',    1,   180.00),
      ('002', 2, 'Brake pads (set)',                  2,    65.00),
