  UPDATE "ExpenseRequest" r
     SET "estimatedTotal" = t.total,
         "actualTotal"    = CASE WHEN r.status = 'DISBURSED' THEN t.total END
    FROM (SELECT "requestId", sum(total) AS total FROM "ExpenseRequestItem" GROUP BY "requestId") t
   WHERE t."requestId" = r.id;

  INSERT INTO "Expense" (id, "schoolId", category, currency, amount, note, "spentOn", "recordedBy", status, "expenseRequestId", "createdAt")
  SELECT 'demo-exp-' || r.id, sid,
         CASE r.type WHEN 'PURCHASE_ORDER' THEN 'Purchase Order' WHEN 'UTILITY_BILL' THEN 'Utilities' WHEN 'FUEL' THEN 'Fuel'
                     WHEN 'SALARY_ADVANCE' THEN 'Staff Salaries' WHEN 'MAINTENANCE' THEN 'Maintenance' ELSE 'Other' END,
         r.currency, r."actualTotal", r.title || ' — ' || r."requestNumber", r."disbursedAt", bursar_id, 'ACTIVE', r.id, r."disbursedAt"
    FROM "ExpenseRequest" r
   WHERE r."schoolId" = sid AND r.status = 'DISBURSED';

  -- ── Subjects, teaching assignments, marks, results ─────────────────────────
  INSERT INTO "Subject" (id, "schoolId", name, code, "maxMark", type, active)
  SELECT 'demo-sub-' || lower(s.code), sid, s.name, s.code, 100, s.type::"SubjectType", true
    FROM (VALUES
      ('MATH', 'Mathematics',           'CORE'),
      ('ENG',  'English Language',      'CORE'),
      ('SHO',  'Shona',                 'CORE'),
      ('SCI',  'Combined Science',      'CORE'),
      ('GEO',  'Geography',             'CORE'),
      ('HIST', 'History',               'CORE'),
      ('ACC',  'Principles of Accounts', 'ELECTIVE'),
      ('COMP', 'Computer Science',      'ELECTIVE')
    ) AS s(code, name, type);

  CREATE TEMP TABLE demo_sub (id TEXT, code TEXT, idx INT);
  INSERT INTO demo_sub
  SELECT 'demo-sub-' || lower(code), code, idx
    FROM unnest(ARRAY['MATH', 'ENG', 'SHO', 'SCI', 'GEO', 'HIST', 'ACC', 'COMP']) WITH ORDINALITY AS u(code, idx);

  -- Terms 1–2 published. Term 3: Form 4 verified and ready to publish, Form 3
  -- being marked, Form 2 part-way, Form 1 just started.
  INSERT INTO "SubjectAssignment" (id, "schoolId", "teacherId", "subjectId", "classId", "termId", "createdAt",
                                   "marksStatus", "marksVerifiedAt", "marksVerifiedById")
  SELECT 'demo-sa-' || c.id || '-' || lower(sub.code) || '-t' || t."termNumber", sid, a.teacher_id, sub.id, c.id, t.id,
         t."startDate" - 3 + TIME '09:00',
         a.status::"AssignmentMarkStatus",
         CASE a.status WHEN 'PUBLISHED' THEN t."endDate" - 5 + TIME '15:00'
                       WHEN 'VERIFIED'  THEN TIMESTAMP '2026-10-09 09:00' + sub.idx * INTERVAL '1 hour' END,
         CASE WHEN a.status IN ('PUBLISHED', 'VERIFIED') THEN a.teacher_id END
    FROM "SchoolClass" c
    JOIN "Level" l ON l.id = c."levelId"
   CROSS JOIN demo_sub sub
   CROSS JOIN "AcademicTerm" t
   CROSS JOIN LATERAL (
     SELECT teachers[1 + ((sub.idx - 1) * 2 + CASE WHEN l."order" <= 2 THEN 0 ELSE 1 END) % nt] AS teacher_id,
            CASE WHEN t.status = 'CLOSED' THEN 'PUBLISHED'
                 WHEN l."order" = 4 THEN 'VERIFIED'
                 WHEN l."order" = 3 THEN 'IN_PROGRESS'
                 WHEN l."order" = 2 THEN CASE WHEN sub.idx <= 5 THEN 'IN_PROGRESS' ELSE 'NOT_STARTED' END
                 ELSE CASE WHEN sub.idx <= 2 THEN 'IN_PROGRESS' ELSE 'NOT_STARTED' END END AS status
   ) a
   WHERE c."schoolId" = sid AND t."schoolId" = sid;

  -- Each student has a steady ability, a liking for some subjects over
  -- others, and some term-to-term noise.
  INSERT INTO "Mark" (id, "schoolId", "studentId", "subjectId", "termId", "rawMark", percentage, "letterGrade",
                      status, "verifiedAt", "enteredBy", "enteredAt")
  SELECT 'demo-mark-' || st.k || '-' || lower(sub.code) || '-t' || st.term_no, sid, st.student_id, sub.id, st.term_id,
         m.raw, m.raw, demo_grade(m.raw),
         (CASE sa."marksStatus" WHEN 'PUBLISHED' THEN 'PUBLISHED' WHEN 'VERIFIED' THEN 'VERIFIED' ELSE 'DRAFT' END)::"MarkStatus",
         CASE WHEN sa."marksStatus" IN ('PUBLISHED', 'VERIFIED') THEN sa."marksVerifiedAt" END,
         sa."teacherId",
         coalesce(sa."marksVerifiedAt", TIMESTAMP '2026-10-12 10:00')
           - (2 + floor(demo_rand(st.k || sub.code || st.term_no || 'at') * 5)) * INTERVAL '1 day'
    FROM demo_st st
    JOIN "SubjectAssignment" sa ON sa."classId" = st.class_id AND sa."termId" = st.term_id
    JOIN demo_sub sub ON sub.id = sa."subjectId"
   CROSS JOIN LATERAL (
     SELECT greatest(3, least(98, round(
              35 + 50 * demo_rand(st.k || 'ability')
              + (demo_rand(st.k || sub.code || 'liking') - 0.5) * 30
              + (demo_rand(st.k || sub.code || st.term_no) - 0.5) * 14)))::numeric AS raw
   ) m
   WHERE sa."marksStatus" IN ('PUBLISHED', 'VERIFIED')
      OR (sa."marksStatus" = 'IN_PROGRESS' AND demo_rand(st.k || sub.code || 'entered') < 0.65);

  -- Published results for Terms 1–2, positioned within each class (ties share
  -- a position, as in lib/results.ts).
  INSERT INTO "TermResult" (id, "schoolId", "studentId", "termId", "totalMarks", percentage, "classPosition",
                            "headRemark", published, "publishedAt")
  SELECT 'demo-result-' || r.k || '-t' || r.term_no, sid, r.student_id, r.term_id, r.total, round(r.total * 100 / r.possible, 2),
         rank() OVER (PARTITION BY r.class_id, r.term_id ORDER BY r.total DESC),
         CASE WHEN r.total * 100 / r.possible >= 75 THEN 'Excellent work. Keep it up.'
              WHEN r.total * 100 / r.possible >= 60 THEN 'Good effort. Aim higher next term.'
              WHEN r.total * 100 / r.possible >= 45 THEN 'Fair. More effort is needed.'
              ELSE 'Below expectations. Please see the class teacher.' END,
         true, r.term_end + 3 + TIME '10:00'
    FROM (SELECT st.k, st.student_id, st.term_id, st.term_no, st.class_id, st.term_end,
                 sum(mk."rawMark") AS total, count(*) * 100 AS possible
            FROM demo_st st
            JOIN "Mark" mk ON mk."studentId" = st.student_id AND mk."termId" = st.term_id
           WHERE st.term_closed
           GROUP BY st.k, st.student_id, st.term_id, st.term_no, st.class_id, st.term_end) r;

