  INSERT INTO "BookCopy" (id, "schoolId", "bookId", "accessionNumber", condition, status)
  SELECT 'demo-copy-' || b.id || '-' || c, sid, b.id,
         'LIB-2026-' || lpad((row_number() OVER (ORDER BY (substr(b.id, 11))::int, c))::text, 4, '0'),
         (CASE WHEN demo_rand(b.id || c) < 0.25 THEN 'NEW' WHEN demo_rand(b.id || c) < 0.75 THEN 'GOOD'
               WHEN demo_rand(b.id || c) < 0.95 THEN 'FAIR' ELSE 'DAMAGED' END)::"CopyCondition",
         'AVAILABLE'
    FROM "Book" b CROSS JOIN LATERAL generate_series(1, b."totalCopies") AS c
   WHERE b."schoolId" = sid;

  INSERT INTO "LibraryMember" (id, "schoolId", "userId")
  SELECT 'demo-member-' || u.id, sid, u.id FROM "User" u WHERE u."schoolId" = sid;

  SELECT array_agg(id ORDER BY id) INTO members FROM "LibraryMember" WHERE "schoolId" = sid;
  nm := array_length(members, 1);

  -- Copy 1 of books 1–14: 1–5 out on loan, 6–9 overdue, 10–14 returned (12–14 late, with fines).
  INSERT INTO "Borrowing" (id, "schoolId", "copyId", "memberId", "checkoutDate", "dueDate", "returnDate",
                           "conditionOnReturn", "fineAmount", "fineSettled", "createdAt")
  SELECT 'demo-borrow-' || i, sid, 'demo-copy-demo-book-' || i || '-1', members[1 + (i - 1) % nm],
         x.out_on, x.out_on + INTERVAL '14 days', x.back_on,
         CASE WHEN x.back_on IS NOT NULL THEN (CASE WHEN i = 14 THEN 'DAMAGED' ELSE 'GOOD' END)::"CopyCondition" END,
         CASE WHEN x.back_on IS NOT NULL
              THEN greatest(0, extract(day FROM x.back_on - (x.out_on + INTERVAL '14 days')))::numeric * 0.50 ELSE 0 END,
         i IN (10, 11, 12), x.out_on
    FROM generate_series(1, 14) AS i
   CROSS JOIN LATERAL (
     SELECT CASE WHEN i <= 5 THEN TIMESTAMP '2026-10-01 10:00' + i * INTERVAL '1 day'
                 WHEN i <= 9 THEN TIMESTAMP '2026-09-10 10:00' + i * INTERVAL '1 day'
                 ELSE TIMESTAMP '2026-08-20 10:00' + i * INTERVAL '1 day' END AS out_on,
            CASE WHEN i IN (10, 11) THEN TIMESTAMP '2026-08-20 10:00' + (i + 10) * INTERVAL '1 day'
                 WHEN i >= 12       THEN TIMESTAMP '2026-08-20 10:00' + (i + 14 + 2 * (i - 11)) * INTERVAL '1 day' END AS back_on
   ) x;

  UPDATE "BookCopy" SET status = 'BORROWED'
   WHERE id IN (SELECT "copyId" FROM "Borrowing" WHERE "schoolId" = sid AND "returnDate" IS NULL);
  UPDATE "BookCopy" SET status = 'LOST', condition = 'DAMAGED' WHERE id = 'demo-copy-demo-book-7-5';
  UPDATE "BookCopy" SET condition = 'DAMAGED' WHERE id = 'demo-copy-demo-book-14-1';

  -- ── Audit trail ────────────────────────────────────────────────────────────
  INSERT INTO "AuditLog" (id, "schoolId", "actorId", action, "entityType", "entityId", detail, "createdAt")
  SELECT 'demo-audit-' || md5(a.action || a.entity_id || a.at::text), sid, a.actor, a.action::"AuditAction",
         a.entity_type, a.entity_id, a.detail, a.at
    FROM (
      SELECT admin_id AS actor, 'CREATE_ACADEMIC_YEAR' AS action, 'AcademicYear' AS entity_type, 'demo-year-2026' AS entity_id,
             '2026 (2026-01-01 to 2026-12-31)' AS detail, TIMESTAMP '2026-01-05 09:00' AS at
      UNION ALL
      SELECT admin_id, 'OPEN_TERM', 'AcademicTerm', id, name, "startDate" - 1 + TIME '09:00' FROM "AcademicTerm" WHERE "schoolId" = sid
      UNION ALL
      SELECT head_id, 'CLOSE_TERM', 'AcademicTerm', id, name, "closedAt" FROM "AcademicTerm" WHERE "schoolId" = sid AND status = 'CLOSED'
      UNION ALL
      SELECT admin_id, 'CREATE_CLASS', 'SchoolClass', id, name, "createdAt" FROM "SchoolClass" WHERE "schoolId" = sid
      UNION ALL
      SELECT bursar_id, 'CREATE_FEE_STRUCTURE', 'FeeStructure', fs.id,
             fs.label || ' ' || fs.currency || ' ' || fs.amount || ' — ' || t.name, fs."createdAt"
        FROM "FeeStructure" fs JOIN "AcademicTerm" t ON t.id = fs."termId" WHERE fs."schoolId" = sid
      UNION ALL
      SELECT head_id, 'BULK_APPLY_FEES', 'AcademicTerm', t.id || ':' || l.id,
             'Applied ' || t.name || ' fees to ' || l.name, t."startDate" + TIME '07:30' + l."order" * INTERVAL '1 minute'
        FROM "AcademicTerm" t CROSS JOIN "Level" l WHERE t."schoolId" = sid AND l."schoolId" = sid AND l."order" <= 4
      UNION ALL
      SELECT admin_id, 'ADMIT_STUDENT', 'Student', s.id, s."admissionNumber" || ' ' || s."fullName" || ' into ' || c.name,
             s."createdAt"
        FROM "Student" s JOIN "SchoolClass" c ON c.id = s."currentClassId"
       WHERE s."schoolId" = sid AND s."admissionDate" >= DATE '2026-01-01'
      UNION ALL
      SELECT bursar_id, 'RECORD_PAYMENT', 'Payment', p.id,
             p.currency || ' ' || p.amount || ' via ' || p.method || ' for ' || s."fullName", p."recordedAt"
        FROM "Payment" p JOIN "Student" s ON s.id = p."studentId" WHERE p."schoolId" = sid
      UNION ALL
      SELECT p."verifiedBy", 'VERIFY_PAYMENT', 'Payment', p.id, p.currency || ' ' || p.amount || ' via ' || p.method, p."verifiedAt"
        FROM "Payment" p WHERE p."schoolId" = sid AND p.status = 'VERIFIED' AND p.method <> 'CASH'
      UNION ALL
      SELECT p."voidedBy", 'VOID_PAYMENT', 'Payment', p.id, 'Duplicate entry', p."voidedAt"
        FROM "Payment" p WHERE p."schoolId" = sid AND p.status = 'VOIDED'
      UNION ALL
      SELECT bursar_id, 'RECORD_EXPENSE', 'Expense', e.id, e.category || ' ' || e.currency || ' ' || e.amount, e."createdAt"
        FROM "Expense" e WHERE e."schoolId" = sid
      UNION ALL
      SELECT e."voidedBy", 'VOID_EXPENSE', 'Expense', e.id, 'Entered twice', e."createdAt" + INTERVAL '2 days'
        FROM "Expense" e WHERE e."schoolId" = sid AND e.status = 'VOIDED'
      UNION ALL
      SELECT r."requestedById", 'CREATE_EXPENSE_REQUEST', 'ExpenseRequest', r.id, r."requestNumber" || ' ' || r.title, r."requestedAt"
        FROM "ExpenseRequest" r WHERE r."schoolId" = sid
      UNION ALL
      SELECT r."requestedById", 'SUBMIT_EXPENSE_REQUEST', 'ExpenseRequest', r.id, r."requestNumber", r."requestedAt" + INTERVAL '5 minutes'
        FROM "ExpenseRequest" r WHERE r."schoolId" = sid AND r.status <> 'DRAFT'
      UNION ALL
      SELECT r."approvedById", 'APPROVE_EXPENSE_REQUEST', 'ExpenseRequest', r.id, r."requestNumber", r."approvedAt"
        FROM "ExpenseRequest" r WHERE r."schoolId" = sid AND r."approvedAt" IS NOT NULL
      UNION ALL
      SELECT r."rejectedById", 'REJECT_EXPENSE_REQUEST', 'ExpenseRequest', r.id, r."requestNumber" || ': ' || r."rejectionReason", r."rejectedAt"
        FROM "ExpenseRequest" r WHERE r."schoolId" = sid AND r."rejectedAt" IS NOT NULL
      UNION ALL
      SELECT r."disbursedById", 'DISBURSE_EXPENSE_REQUEST', 'ExpenseRequest', r.id,
             r."requestNumber" || ' ' || r.currency || ' ' || r."actualTotal", r."disbursedAt"
        FROM "ExpenseRequest" r WHERE r."schoolId" = sid AND r."disbursedAt" IS NOT NULL
      UNION ALL
      SELECT sa."marksVerifiedById", 'VERIFY_MARKS', 'SubjectAssignment', sa.id, s.name || ', ' || c.name || ', ' || t.name, sa."marksVerifiedAt"
        FROM "SubjectAssignment" sa
        JOIN "Subject" s ON s.id = sa."subjectId" JOIN "SchoolClass" c ON c.id = sa."classId" JOIN "AcademicTerm" t ON t.id = sa."termId"
       WHERE sa."schoolId" = sid AND sa."marksVerifiedAt" IS NOT NULL
      UNION ALL
      SELECT head_id, 'PUBLISH_RESULTS', 'TermResult', c.id || ':' || t.id,
             'Published ' || count(*) || ' results for ' || c.name || ' — ' || t.name, max(tr."publishedAt")
        FROM "TermResult" tr
        JOIN "Enrollment" e ON e."studentId" = tr."studentId" AND e."termId" = tr."termId"
        JOIN "SchoolClass" c ON c.id = e."classId" JOIN "AcademicTerm" t ON t.id = tr."termId"
       WHERE tr."schoolId" = sid
       GROUP BY c.id, c.name, t.id, t.name
      UNION ALL
      SELECT admin_id, 'CREATE_ASSET', 'Asset', a.id, a."tagNumber" || ' ' || a.name, a."createdAt"
        FROM "Asset" a WHERE a."schoolId" = sid
      UNION ALL
      SELECT d."recordedBy", 'DISPOSE_ASSET', 'Asset', d."assetId", d.method || ': ' || d.reason, d."createdAt"
        FROM "AssetDisposal" d WHERE d."schoolId" = sid
      UNION ALL
      SELECT librarian_id, 'CHECKOUT_BOOK', 'Borrowing', b.id, bk.title, b."checkoutDate"
        FROM "Borrowing" b JOIN "BookCopy" c ON c.id = b."copyId" JOIN "Book" bk ON bk.id = c."bookId" WHERE b."schoolId" = sid
      UNION ALL
      SELECT librarian_id, 'RETURN_BOOK', 'Borrowing', b.id, bk.title, b."returnDate"
        FROM "Borrowing" b JOIN "BookCopy" c ON c.id = b."copyId" JOIN "Book" bk ON bk.id = c."bookId"
       WHERE b."schoolId" = sid AND b."returnDate" IS NOT NULL
    ) a;

  DROP TABLE demo_st;
  DROP TABLE demo_pay;
  DROP TABLE demo_sub;

  RAISE NOTICE 'Demo data loaded: % students, % payments, % marks, % expenses.',
    (SELECT count(*) FROM "Student" WHERE "schoolId" = sid),
    (SELECT count(*) FROM "Payment" WHERE "schoolId" = sid),
    (SELECT count(*) FROM "Mark"    WHERE "schoolId" = sid),
    (SELECT count(*) FROM "Expense" WHERE "schoolId" = sid);
END
$demo$;

DROP TABLE demo_csv;
DROP FUNCTION demo_rand(TEXT);
DROP FUNCTION demo_grade(NUMERIC);
